// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 constant SEED = 1 ether;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, SEED - 1); // admissible: 0 < amount < contract balance
        vm.deal(address(c), SEED);           // c holds SEED wei

        // c's owner is this test contract (msg.sender at deployment),
        // so the caller/recipient of withdraw is address(this).
        uint256 before = address(this).balance;
        vm.prank(address(this));
        c.withdraw(amount);
        uint256 after_ = address(this).balance;

        // General rule: a successful withdraw(amount) pays out exactly `amount`.
        assertTrue(after_ == before + amount, "withdraw must pay exactly _value");
    }
}
